def evolve(state: str, offsets: list[int], t: int) -> str:
    if t == 0:
        return state

    n = len(state)
    mask = (1 << n) - 1
    value = int(state, 2)
    shifts = [offset % n for offset in offsets]

    while t:
        if t & 1:
            result = 0
            for shift in shifts:
                result ^= (
                    (value << shift) | (value >> (n - shift))
                ) & mask
            value = result

        t >>= 1
        if t:
            shifts = [(shift * 2) % n for shift in shifts]

    return format(value, f"0{n}b")
